import{_ as s,l as m,o as t,c as l,v as e,p as n,x as r,d as o,i as h,S as d}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"风险中性测度","description":"","frontmatter":{"title":"风险中性测度","date":"2026-09-10T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/risk-neutral-measure.md","filePath":"quant/risk-neutral-measure.md","lastUpdated":1789023840000}'),u={name:"quant/risk-neutral-measure.md"};function E(p,a,c,B,_,A){const i=m("Mermaid");return t(),l("div",null,[a[1]||(a[1]=e('<h1 id="风险中性测度" tabindex="-1">风险中性测度 <a class="header-anchor" href="#风险中性测度" aria-label="Permalink to &quot;风险中性测度&quot;">​</a></h1><div class="epigraph"><p>无套利当且仅当存在等价测度 $Q$，使贴现资产价格为 $Q$-鞅。价格是 $Q$ 下贴现期望，不是 $P$ 下用 $\\mu$ 折现。</p><footer>—— 据 Harrison and Pliska, Stochastic Processes and their Applications, 1981；Shreve, Stochastic Calculus for Finance II, 2004, 第 5 章整理</footer></div><p>上一课<a href="/quant/girsanov-measure">Girsanov 测度变换</a>给出任意漂移平移。缺口是选出那一个 \\(\\theta\\)：让贴现标的 \\(S/B\\) 成为鞅。这不是投资者风险中性的心理学假设，而是无套利的概率翻译。本课只钉这条等价，不讨论唯一性——唯一性是下一课完备市场。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>真实测度 \\(P\\) 下 \\(\\mathrm d S=\\mu S\\,\\mathrm d t+\\sigma S\\,\\mathrm d W\\)，\\(\\mu\\) 含风险溢价，不可直接拿来贴现取期望：不同资产 \\(\\mu\\) 不同，组合的折现率没有单一数字。缺口是换到 \\(Q\\sim P\\)，使 \\(\\mathrm d S=r S\\,\\mathrm d t+\\sigma S\\,\\mathrm d W^Q\\)（利率先当常数）。此时 \\(\\mathrm e^{-rt}S_t\\) 为 \\(Q\\)-鞅，未定权益 \\(H\\) 的价格为 \\(\\mathrm e^{-rT}\\mathbb E_Q[H]\\)。没有 \\(Q\\)，复制价格和对冲比率都还没有概率表达式。</p><p>Harrison–Kreps / Harrison–Pliska 把「无套利」与「存在等价鞅测度」焊在一起。本课用这条第一基本定理的可用形式，不把离散模型的证明重写。</p><h3 id="风险中性不是「投资者不在乎风险」" tabindex="-1">风险中性不是「投资者不在乎风险」 <a class="header-anchor" href="#风险中性不是「投资者不在乎风险」" aria-label="Permalink to &quot;风险中性不是「投资者不在乎风险」&quot;">​</a></h3><p>\\(Q\\) 下超额回报为零，是因为已经把风险溢价吸进测度。\\(P\\) 下投资者仍可以厌恶风险，\\(\\mu\\gt r\\) 完全合法。把 \\(Q\\) 读成偏好假设，后面不全市场里「许多 \\(Q\\)」会变成许多偏好，对象错位。\\(Q\\) 是定价测度，不是描述测度。</p><p><span class="marginnote">贴现因子 \\(B_t=\\mathrm e^{rt}\\) 是本课的计价物。随机利率时要换成储蓄账户 \\(\\exp(\\int r)\\)，预告在<a href="/quant/stochastic-rate-preview">利率不是常数</a>。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>市场含无风险 \\(B\\) 与 GBM 标的 \\(S\\)。取 \\(\\theta=(\\mu-r)/\\sigma\\)（\\(\\sigma\\neq 0\\)），Girsanov 给出 \\(Q\\)。则</p> \\[\\mathrm d S_t=r S_t\\,\\mathrm d t+\\sigma S_t\\,\\mathrm d W^Q_t, \\]<p>且 \\(V_t=\\mathrm e^{-r(T-t)}\\mathbb E_Q[H\\mid\\mathcal F_t]\\) 是贴现鞅的可料表示候选。欧式看涨 \\(H=(S_T-K)^+\\) 的价格因此是 \\(Q\\) 下对数正态期望——闭式留给 Black 公式课。本课只锁定：\\(P\\) 中的 \\(\\mu\\) 退出定价公式。</p><p>复制：若 \\(H\\) 可写成 \\(\\int\\Delta\\,\\mathrm d S\\) 加货币市场，则该 \\(\\Delta\\) 的损益在 \\(Q\\) 下为鞅，初值等于上述期望。对冲细节是<a href="/quant/replicating-delta">复制与 delta</a>。</p>',14)),(t(),n(d,null,{default:r(()=>[h(i,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E7%89%A9%E7%90%86%E6%B5%8B%E5%BA%A6%EF%BC%9A%E6%BC%82%E7%A7%BB%20mu%22%5D%20--%3E%20THETA%5B%22theta%20%E7%AD%89%E4%BA%8E%20mu%20%E5%87%8F%20r%20%E5%86%8D%E9%99%A4%20sigma%22%5D%0A%20%20THETA%20--%3E%20Q%5B%22%E7%AD%89%E4%BB%B7%E9%9E%85%E6%B5%8B%E5%BA%A6%22%5D%0A%20%20Q%20--%3E%20PRICE%5B%22%E4%BB%B7%E6%A0%BC%E7%AD%89%E4%BA%8E%20Q%20%E4%B8%8B%E8%B4%B4%E7%8E%B0%E6%9C%9F%E6%9C%9B%22%5D%0A%20%20PRICE%20--%3E%20NEXT%5B%22%E4%B8%8B%E4%B8%80%E8%AF%BE%EF%BC%9A%E5%94%AF%E4%B8%80%E6%80%A7%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>无套利禁止「零投入、非负收益且正概率严格为正」。若贴现 \\(S\\) 在某等价测度下为鞅，则任何可积可料策略的贴现价值也是局部鞅，取期望得不到严格优势——存在 \\(Q\\) 推出无套利（技术条件上要可容许策略）。反过来，有套利则没有任何 \\(Q\\) 能让所有贴现资产走平。这是第一基本定理的方向。\\(\\theta=(\\mu-r)/\\sigma\\) 把每个噪声源上的超额回报标准化，正是 Girsanov 的旋钮对准「取消 \\(\\mu-r\\)」。</p><p>\\(Q\\) 与 \\(P\\) 在零集上一致，故 \\(S\\gt 0\\)、\\(T\\lt \\infty\\) 等 \\(P\\)-a.s. 事件在定价里原样保留。改变的只是路径权重，不是支撑集。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课假设常数 \\(r\\)、一个布朗、\\(\\sigma\\neq 0\\)，以便 \\(Q\\) 立刻存在。多资产、随机 \\(r\\)、跳，会让「存在」与「唯一」分开。后课默认：欧式未定权益先写成 \\(\\mathrm e^{-rT}\\mathbb E_Q[H]\\)；\\(P\\) 下的 \\(\\mu\\) 不进价格。下一课<a href="/quant/complete-unique-measure">完备市场与唯一测度</a>问这个 \\(Q\\) 是不是仅有的一个。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>无套利 \\(\\Leftrightarrow\\) 存在等价测度使贴现资产为鞅。</li><li>风险中性是定价测度，不是偏好假设；\\(\\mu\\) 退出公式。</li><li>GBM 下 \\(\\theta=(\\mu-r)/\\sigma\\) 经 Girsanov 给出 \\(Q\\)。</li><li>价格 \\(=Q\\) 下贴现期望；波动率不变。</li><li>出处：Harrison–Pliska 1981；Shreve SDE II 第 5 章。</li></ul>',7))])}const Q=s(u,[["render",E]]);export{P as __pageData,Q as default};
